/*==================================================
   Banco de Dados: Dados Demograficos Br
  --------------------------------------------------
  Descrição:
  Estrutura relacional otimizada para armazenamento 
  e carga eficiente de dados demográficos (UF, cidade, 
  região e população).

  Objetivo:
  Servir como base para análises exploratórias, 
  construção de dashboards e estudos estatísticos, 
  garantindo rapidez na ingestão e consistência dos dados.

  Considerações de Performance:
  - Uso de SET NOCOUNT ON para reduzir overhead de mensagens
  - Possibilidade de uso de transações para controle de carga
  - Estrutura compatível com cargas em lote (batch insert)
  - Preparado para evolução com índices adicionais conforme necessidade analítica

==================================================*/


/*==================================================
   Criação do Banco de Dados
==================================================*/

/*CREATE DATABASE dados_demograficos_br;
GO

USE dados_demograficos_br;
GO
*/

/*==================================================
  Reset da Tabela
==================================================*/
IF OBJECT_ID('dbo.populacao_br', 'U') IS NOT NULL
BEGIN
    DROP TABLE dbo.populacao_br;
END
GO

/*==================================================
  Criação da Tabela
==================================================*/


CREATE TABLE populacao_br (
    uf CHAR(2),                 
    cidade VARCHAR(100),      
    regiao VARCHAR(30),       
    populacao INT,            
    ehcapital BIT,

    CONSTRAINT pk_populacao_br 
        PRIMARY KEY (uf, cidade)
);
GO

truncate table dados_demograficos_br.dbo.populacao_br

declare @dt_ini datetime = getdate()

SET NOCOUNT ON -- não aparece mais (1 row affected) 
BEGIN TRANSACTION 



print 'Tempo total: ' + convert(varchar, getdate() - @dt_ini, 114)
COMMIT

